<script setup lang="ts">
import { computed, ref } from "vue";
import { useRouter } from "vue-router";
import { api, getApiErrorMessage } from "../lib/api";
import { useToastStore } from "../stores/toasts";
interface Status { id:number; name:string; is_initial:boolean; is_final:boolean; marks_delivered:boolean }
interface Row { key:string; sheet:string; source_row:number; ficha:string|null; customer:string|null; phone:string|null; received_at:string|null; category:string|null; brand:string|null; model:string|null; motive:string|null; legacy_status:string|null; color_meaning:string|null; suggested_status_id:number|null; suggested_status_name:string; state:"ready"|"warning"|"duplicate"|"blocked"|"already_imported"; problems:string[]; warnings:string[] }
interface Preview { company_id:number; company_name:string; filename:string; file_sha256:string; preview_token:string; sheets:Array<{name:string;rows:number;ready:number;warning:number;duplicate:number;blocked:number;already_imported:number}>; counts:Record<string,number>; statuses:Status[]; rows:Row[] }
interface Result { imported:number; skipped:number; rows:Array<{key:string;result:string;work_order_id:number|null;work_order_number?:number;reasons?:string[]}> }
const router=useRouter(),toast=useToastStore();
const file=ref<File|null>(null),preview=ref<Preview|null>(null),result=ref<Result|null>(null),loading=ref(false),importing=ref(false),sheetFilter=ref("Todas");
const includeDuplicates=ref<Record<string,boolean>>({}),statusMappings=ref<Record<string,number|null>>({}),corrections=ref<Record<string,{customer_name:string;phone:string;received_at:string;category:string}>>({});
const duplicates=computed(()=>preview.value?.rows.filter(row=>row.state==="duplicate")??[]);
const remainingBlocked=computed(()=>(preview.value?.rows??[]).filter(row=>row.state==="blocked").filter(row=>{const correction=corrections.value[row.key];return !correction?.customer_name.trim()||!correction.received_at||!correction.category.trim()}).length);
const blockedResults=computed(()=>result.value?.rows.filter(row=>row.result==="blocked")??[]);
const legacyStatuses=computed(()=>[...new Set((preview.value?.rows??[]).map(statusKey))]);
const visibleRows=computed(()=>{const rows=preview.value?.rows??[];return sheetFilter.value==="Todas"?rows:rows.filter(row=>row.sheet===sheetFilter.value)});
function statusKey(row:Row){return row.color_meaning?.trim()?`Color: ${row.color_meaning.trim()}`:`Estado: ${row.legacy_status?.trim()||"(Sin estado informado)"}`}
function selectFile(event:Event){file.value=(event.target as HTMLInputElement).files?.[0]??null;preview.value=null;result.value=null;includeDuplicates.value={};statusMappings.value={};corrections.value={}}
async function makePreview(){if(!file.value)return;loading.value=true;preview.value=null;result.value=null;try{const form=new FormData();form.append("file",file.value);const {data}=await api.post<Preview>("/work-orders/import/preview",form);preview.value=data;for(const row of data.rows){if(row.state==="duplicate")includeDuplicates.value[row.key]=false;if(row.suggested_status_id!==null)statusMappings.value[statusKey(row)]=row.suggested_status_id;corrections.value[row.key]={customer_name:row.customer??"",phone:row.phone??"",received_at:row.received_at?.slice(0,10)??"",category:row.category??""}}}catch(error){toast.push(getApiErrorMessage(error,"No se pudo leer el archivo."),"error")}finally{loading.value=false}}
function confirmImport(){if(!file.value||!preview.value)return;const included=duplicates.value.filter(row=>includeDuplicates.value[row.key]).length;const ok=window.confirm(`Empresa destino: ${preview.value.company_name}. Se importarán las filas válidas y corregidas; ${remainingBlocked.value} que sigan incompletas se omitirán. Incluiste ${included} de ${duplicates.value.length} filas ambiguas. ¿Confirmás?`);if(!ok)return;void sendImport()}
async function sendImport(){const selectedFile=file.value,currentPreview=preview.value;if(!selectedFile||!currentPreview)return;importing.value=true;try{const rows=currentPreview.rows.map(row=>({key:row.key,include:row.state!=="duplicate"||includeDuplicates.value[row.key]===true,status_id:statusMappings.value[statusKey(row)]??row.suggested_status_id,...corrections.value[row.key],received_at:corrections.value[row.key].received_at||null}));const form=new FormData();form.append("file",selectedFile);form.append("preview_token",currentPreview.preview_token);form.append("decisions",JSON.stringify({rows}));const {data}=await api.post<Result>("/work-orders/import/confirm",form);result.value=data;toast.push(`Importación terminada: ${data.imported} órdenes nuevas.`,"success")}catch(error){toast.push(getApiErrorMessage(error,"No se pudo completar la importación."),"error")}finally{importing.value=false}}
function date(value:string|null){return value?new Intl.DateTimeFormat("es-AR",{dateStyle:"short"}).format(new Date(value)):"—"}
function label(state:Row["state"]){return({ready:"Lista",warning:"Advertencia",duplicate:"Revisar duplicado",blocked:"Bloqueada",already_imported:"Ya importada"})[state]}
</script>
<template>
  <section class="import-page">
    <header class="card page-header import-header"><div><button class="btn btn--ghost btn--sm" @click="router.push('/app/work-orders')">← Órdenes de trabajo</button><h1>Importar trabajos</h1><p class="text-secondary">Cargá el registro, revisá cómo se interpretará y confirmá la importación.</p></div><div v-if="preview" class="destination"><span>Empresa destino</span><strong>{{preview.company_name}}</strong></div></header>
    <section class="card import-section"><div class="step-title"><b>1</b><div><h2>Seleccionar registro</h2><p class="text-secondary">Se leen las hojas detalladas: Maquinas 2024, 2025, Desarmados y Hoja1.</p></div></div><div class="file-row"><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="selectFile"><button class="btn btn--primary" :disabled="!file||loading||importing" @click="makePreview">{{loading?'Leyendo…':'Generar vista previa'}}</button></div><small class="text-muted">Solo .xlsx · máximo 15 MB. La vista previa no guarda datos.</small></section>
    <template v-if="preview">
      <div class="counts"><article class="card count ready"><span>Listas</span><strong>{{preview.counts.ready??0}}</strong></article><article class="card count warning"><span>Advertencias</span><strong>{{preview.counts.warning??0}}</strong></article><article class="card count duplicate"><span>Posibles duplicados</span><strong>{{preview.counts.duplicate??0}}</strong></article><article class="card count blocked"><span>Bloqueadas</span><strong>{{preview.counts.blocked??0}}</strong></article><article class="card count imported"><span>Ya importadas</span><strong>{{preview.counts.already_imported??0}}</strong></article></div>
      <section class="card import-section"><div class="step-title"><b>2</b><div><h2>Revisar interpretación</h2><p class="text-secondary">La ficha original se conserva como referencia, no se usa como número único.</p></div></div>
        <div class="sheets"><div v-for="item in preview.sheets" :key="item.name"><strong>{{item.name}}</strong><span>{{item.rows.toLocaleString('es-AR')}} filas</span><small>{{item.ready}} listas · {{item.warning}} con advertencia · {{item.duplicate}} ambiguas · {{item.blocked}} bloqueadas</small></div></div>
        <p v-if="duplicates.length" class="callout callout--warn"><strong>Filas ambiguas:</strong> están desmarcadas. Marcá solo las que sean trabajos distintos que quieras importar.</p>
        <p v-if="preview.counts.blocked" class="callout callout--bad"><strong>{{preview.counts.blocked}} filas bloqueadas:</strong> falta cliente, fecha válida o categoría; se omiten y las demás pueden importarse.</p>
        <div v-if="legacyStatuses.length&&preview.statuses.length" class="mapping"><h3>Equivalencia del color/estado</h3><p class="text-secondary">Se prioriza el significado del color porque distingue, por ejemplo, lo entregado de lo listo para entregar. Se preservan ambos valores originales.</p><label v-for="legacy in legacyStatuses" :key="legacy"><span>{{legacy}}</span><select v-model.number="statusMappings[legacy]"><option v-for="status in preview.statuses" :key="status.id" :value="status.id">{{status.name}}</option></select></label></div>
        <div class="filter"><label for="sheet">Hoja</label><select id="sheet" v-model="sheetFilter"><option>Todas</option><option v-for="item in preview.sheets" :key="item.name">{{item.name}}</option></select><span>{{visibleRows.length.toLocaleString('es-AR')}} filas visibles</span></div>
        <div class="table-scroll"><table class="table import-table"><thead><tr><th>Incluir</th><th>Origen</th><th>Ficha</th><th>Fecha</th><th>Cliente</th><th>Equipo</th><th>Motivo</th><th>Estado original</th><th>Estado propuesto</th><th>Resultado</th></tr></thead><tbody>
          <tr v-for="row in visibleRows" :key="row.key"><td data-label="Incluir"><input v-if="row.state==='duplicate'" v-model="includeDuplicates[row.key]" type="checkbox" :aria-label="`Incluir ${row.sheet} fila ${row.source_row}`"><span v-else-if="row.state==='blocked'||row.state==='already_imported'">—</span><span v-else>✓</span></td><td data-label="Origen">{{row.sheet}} · {{row.source_row}}</td><td data-label="Ficha">{{row.ficha||'—'}}</td><td data-label="Fecha"><input v-if="row.state==='blocked'" v-model="corrections[row.key].received_at" type="date"><span v-else>{{date(row.received_at)}}</span></td><td data-label="Cliente"><template v-if="row.state==='blocked'"><input v-model="corrections[row.key].customer_name" placeholder="Corregir cliente"><input v-model="corrections[row.key].phone" placeholder="Teléfono (opcional)"></template><template v-else><strong>{{row.customer||'Sin cliente'}}</strong><small>{{row.phone||'Sin teléfono'}}</small></template></td><td data-label="Equipo"><template v-if="row.state==='blocked'"><input v-model="corrections[row.key].category" placeholder="Corregir categoría"></template><template v-else>{{[row.category,row.brand,row.model].filter(Boolean).join(' · ')||'Sin categoría'}}</template></td><td data-label="Motivo">{{row.motive||'Sin detalle'}}</td><td data-label="Estado original">{{row.legacy_status||'Sin estado'}}<small>{{row.color_meaning||'Sin significado de color'}}</small></td><td data-label="Estado propuesto">{{statusMappings[statusKey(row)]?preview.statuses.find(s=>s.id===statusMappings[statusKey(row)])?.name:row.suggested_status_name}}</td><td data-label="Resultado"><span :class="['tag',`tag--${row.state}`]">{{label(row.state)}}</span><small v-if="row.problems.length">{{row.problems.join(' ')}}</small><small v-else-if="row.warnings.length">{{row.warnings.join(' ')}}</small></td></tr>
        </tbody></table></div>
        <p class="text-muted">Archivo: {{preview.filename}} · Las hojas ocultas de resumen no se importan. Las filas incompletas se pueden corregir en esta tabla; las que sigan incompletas se omitirán.</p><div class="actions"><button class="btn btn--ghost" :disabled="loading||importing" @click="makePreview">Volver a previsualizar</button><button class="btn btn--primary" :disabled="importing||loading" @click="confirmImport">{{importing?'Importando…':`Confirmar importación en ${preview.company_name}`}}</button></div>
      </section>
      <section v-if="result" class="card result"><div><h2>Importación finalizada</h2><p>{{result.imported}} órdenes nuevas · {{result.skipped}} filas omitidas o ya importadas.</p><ul v-if="blockedResults.length"><li v-for="row in blockedResults" :key="row.key">{{row.key}}: {{row.reasons?.join(' ')}}</li></ul></div><button class="btn btn--primary" @click="router.push('/app/work-orders')">Ver órdenes</button></section>
    </template>
  </section>
</template>
<style scoped>
.import-page{display:grid;gap:18px}.import-header{align-items:flex-start;gap:18px}.import-header h1{margin:14px 0 4px}.import-header p{margin:0}.destination{display:grid;gap:4px;padding:11px 15px;border:1px solid rgba(96,165,250,.4);border-radius:12px;background:rgba(59,130,246,.08)}.destination span,.count span{font-size:12px;color:var(--color-text-muted)}.import-section{padding:20px}.step-title{display:flex;gap:12px;margin-bottom:18px}.step-title>b{display:grid;place-items:center;flex:0 0 30px;height:30px;border-radius:50%;background:rgba(59,130,246,.16);color:#60a5fa}.step-title h2{margin:0 0 4px}.step-title p{margin:0}.file-row{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:9px}.counts{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}.count{display:grid;gap:8px;padding:15px;border-top:3px solid #64748b}.count strong{font-size:28px}.count.ready{border-color:#22c55e}.count.warning{border-color:#f59e0b}.count.duplicate{border-color:#a78bfa}.count.blocked{border-color:#ef4444}.sheets{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:14px 0}.sheets>div{display:grid;gap:4px;padding:12px;border:1px solid var(--color-border);border-radius:10px}.sheets span,.sheets small{color:var(--color-text-secondary);font-size:13px}.callout{padding:12px 14px;border-radius:10px}.callout--warn{background:rgba(245,158,11,.12);color:#fbbf24}.callout--bad{background:rgba(239,68,68,.12);color:#fca5a5}.mapping{margin:18px 0}.mapping h3{margin-bottom:4px}.mapping label{display:grid;grid-template-columns:1fr 1fr;gap:12px;align-items:center;max-width:720px;padding:6px 0}.mapping select,.filter select{padding:8px;border:1px solid var(--color-border);border-radius:8px;background:var(--color-surface);color:var(--color-text)}.filter{display:flex;align-items:center;gap:10px;margin:14px 0}.filter span{margin-left:auto;color:var(--color-text-muted)}.table-scroll{max-height:70vh;overflow:auto;border:1px solid var(--color-border);border-radius:12px}.import-table{min-width:1150px;margin:0}.import-table td input{max-width:160px;padding:6px;border:1px solid var(--color-border);border-radius:7px;background:var(--color-surface);color:var(--color-text)}.import-table td small{display:block;max-width:250px;margin-top:3px;color:var(--color-text-muted)}.tag{display:inline-flex;padding:4px 8px;border-radius:999px;font-size:12px;font-weight:700;white-space:nowrap}.tag--ready{background:rgba(34,197,94,.14);color:#4ade80}.tag--warning{background:rgba(245,158,11,.14);color:#fbbf24}.tag--duplicate{background:rgba(167,139,250,.15);color:#c4b5fd}.tag--blocked{background:rgba(239,68,68,.14);color:#fca5a5}.tag--already_imported{background:rgba(100,116,139,.18);color:#cbd5e1}.actions,.result{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:14px}.result h2,.result p{margin:0 0 5px}@media(max-width:850px){.counts{grid-template-columns:repeat(2,minmax(0,1fr))}.sheets{grid-template-columns:repeat(2,minmax(0,1fr))}.import-header,.result{flex-direction:column}.destination{width:100%}.actions{flex-direction:column-reverse}.actions .btn{width:100%}}@media(max-width:600px){.import-section{padding:14px}.mapping label{grid-template-columns:1fr}.filter{flex-wrap:wrap}.filter span{width:100%;margin:0}}
</style>
